function sourceReceipt(){const files={};const visit=relative=>{for(const entry of readdirSync(join(repo,relative),{withFileTypes:true})){const name=relative+'/'+entry.name;if(entry.isDirectory())visit(name);else if(entry.isFile())files[name]=sha(readFileSync(join(repo,name)));}};for(const relative of ['apps/server/src','apps/web/src','apps/web/public','apps/web/dist','packages/shared/src','packages/shared/dist','packages/agent/src','packages/agent/dist'])visit(relative);const sorted=Object.fromEntries(Object.entries(files).sort(([a],[b])=>a.localeCompare(b))),aggregate=sha(JSON.stringify(sorted));writeFileSync(join(out,'source-'+aggregate+'.json'),JSON.stringify(sorted,null,2));return aggregate;}
